	pop de
	call ccpint
	ld hl,(s)
	push hl
	ld hl,2
	add hl,sp
	call ccgint
	pop de
	call ccxor
	ld (s),hl
	jp sc_L3
sc_L5:
sc_L1:
	pop bc
	pop bc
	ret
main:
	ld hl,sc_L0+0
	push hl
	ld a,1
	call puts
	pop bc
	ld a,0
	call bench
	ld hl,(s)
	push hl
	ld a,1
	call printn
	pop bc
sc_L6:
	ret
sc_L0:
	db 103,111,0
s:
	dw 0

